private static func handshake() -> Bool {
    let traceStarted = ProcessInfo.processInfo.systemUptime
    let traceStartedUnix = Date().timeIntervalSince1970
    var traceEvents: [[String: Any]] = []
    var traceReply: [UInt8] = []
    var traceResult = false
    // One bounded line per original probe. File order identifies attempts;
    // no shared counter, extra network probe, or altered retry policy.
    defer {
        let savedErrno = errno
        defer { errno = savedErrno }
        let record: [String: Any] = [
            "kind": "integrated-original-ipv4-handshake",
            "started_unix": traceStartedUnix,
            "started_uptime": traceStarted,
            "finished_uptime": ProcessInfo.processInfo.systemUptime,
            "events": traceEvents,
            "reply_buffer": traceReply,
            "returned": traceResult,
            "errno_note": "errno is captured immediately; it is diagnostic only and may be stale after success"
        ]
        if let data = try? JSONSerialization.data(withJSONObject: record, options: [.sortedKeys]),
           data.count <= 8_192 {
            do {
                try FileHandle.standardError.write(contentsOf:
                    Data("IG_HANDSHAKE_TRACE ".utf8) + data + Data([10]))
            } catch { /* Logging must not replace the original probe result. */ }
        }
    }
    func observed<Value: BinaryInteger>(_ stage: String, _ operation: () -> Value) -> Value {
        let began = ProcessInfo.processInfo.systemUptime
        let value = operation()
        let capturedErrno = errno
        let ended = ProcessInfo.processInfo.systemUptime
        traceEvents.append([
            "stage": stage, "returncode": Int64(value), "errno": capturedErrno,
            "started_uptime": began, "finished_uptime": ended,
            "elapsed_seconds": ended - began
        ])
        errno = capturedErrno
        return value
    }
    let fd = observed("socket", { Darwin.socket(AF_INET, SOCK_STREAM, 0) })
    guard fd >= 0 else { return false }
