    address.sin_family = sa_family_t(AF_INET)
    address.sin_port = UInt16(1080).bigEndian
    guard observed("inet_pton", { inet_pton(AF_INET, "127.0.0.1", &address.sin_addr) }) == 1 else { return false }
    let connected = withUnsafePointer(to: &address) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { pointer in
            observed("connect", { Darwin.connect(fd, pointer, socklen_t(MemoryLayout<sockaddr_in>.size)) })
        }
    }
    guard connected == 0 else { return false }
    let greeting: [UInt8] = [5, 1, 0]
    guard greeting.withUnsafeBytes({ buffer in
        observed("send", { Darwin.send(fd, buffer.baseAddress, buffer.count, 0) })
